async function seedWorkspace(db, owner) {
  const t = Date.now();
  const statements = [];
  const companyIds = companies2.map(() => id());
  companies2.forEach((c, i) => {
    statements.push(
      db.prepare(
        `INSERT INTO companies (id, owner_sub, name, domain, industry, size, location, hue, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(companyIds[i], owner, c.name, c.domain, c.industry, c.size, c.location, hueFor(c.name), t - (60 - i * 5) * DAY, t - i * DAY)
    );
  });
  const contactIds = people.map(() => id());
  people.forEach(([first, last, title, companyIndex, status], i) => {
    const domain = companyIndex >= 0 ? companies2[companyIndex].domain : "example.com";
    const email = `${first.toLowerCase().normalize("NFD").replace(/[^a-z]/g, "")}.${last.toLowerCase()}@${domain}`;
    const lastActivity = t - i * 7 % 29 * DAY - i % 5 * 36e5;
    statements.push(
      db.prepare(
        `INSERT INTO contacts (id, owner_sub, company_id, first_name, last_name, email, phone, title, status, hue, last_activity_at, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        contactIds[i],
        owner,
        companyIndex >= 0 ? companyIds[companyIndex] : null,
        first,
        last,
        email,
        `+1 (555) 01${String(i).padStart(2, "0")}-${String(2e3 + i * 37).slice(-4)}`,
        title,
        status,
        hueFor(first + last),
        lastActivity,
        t - (90 - i * 3) * DAY,
        lastActivity
      )
    );
  });
  const dealIds = dealSeeds.map(() => id());
  dealSeeds.forEach(([title, companyIndex, contactIndex, stage, value, closeOffset], i) => {
    const closeDate = new Date(t + closeOffset * DAY).toISOString().slice(0, 10);
    statements.push(
      db.prepare(
        `INSERT INTO deals (id, owner_sub, title, company_id, contact_id, value, stage, position, close_date, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        dealIds[i],
        owner,
        title,
        companyIndex >= 0 ? companyIds[companyIndex] : null,
        contactIds[contactIndex],
        value,
        stage,
        i,
        closeDate,
        t - (45 - i * 2) * DAY,
        t - i % 6 * DAY
      )
    );
  });
  const historic = [
    ["Starter rollout", 0, 14e3, 35],
    ["Reporting pack", 1, 8200, 48],
    ["Seat expansion", 2, 26e3, 62],
    ["Onboarding services", 3, 5400, 75],
    ["Analytics licence", 4, 31e3, 88],
    ["Field tooling", 5, 44e3, 101],
    ["Advisory package", 6, 19e3, 120],
    ["Content platform", 7, 12500, 134],
    ["Pilot extension", 2, 17500, 150],
    ["Integration work", 1, 9900, 166]
  ];
  historic.forEach(([title, companyIndex, value, daysAgo], i) => {
    statements.push(
      db.prepare(
        `INSERT INTO deals (id, owner_sub, title, company_id, contact_id, value, stage, position, close_date, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, 'won', ?, ?, ?, ?)`
      ).bind(
        id(),
        owner,
        title,
        companyIds[companyIndex],
        contactIds[companyIndex * 2],
        value,
        100 + i,
        new Date(t - daysAgo * DAY).toISOString().slice(0, 10),
        t - (daysAgo + 20) * DAY,
        t - daysAgo * DAY
      )
    );
  });
  const kinds = ["note", "call", "email", "meeting"];
  for (let i = 0; i < 36; i++) {
    const contactIndex = i * 5 % people.length;
    const dealIndex = i % 3 === 0 ? i * 7 % dealSeeds.length : -1;
    statements.push(
      db.prepare(
        `INSERT INTO activities (id, owner_sub, kind, body, contact_id, deal_id, company_id, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        id(),
        owner,
        kinds[i % kinds.length],
        noteBodies[i % noteBodies.length],
        contactIds[contactIndex],
        dealIndex >= 0 ? dealIds[dealIndex] : null,
        people[contactIndex][3] >= 0 ? companyIds[people[contactIndex][3]] : null,
        t - i * 0.8 * DAY - i % 7 * 36e5
      )
    );
  }
  taskTitles.forEach((title, i) => {
    const due = i < 3 ? t + i * 36e5 * 4 : t + (i - 2) * DAY + 9 * 36e5;
    statements.push(
      db.prepare(
        `INSERT INTO tasks (id, owner_sub, title, due_at, done_at, contact_id, deal_id, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(
        id(),
        owner,
        title,
        due,
        i === 7 || i === 9 ? t - DAY : null,
        contactIds[i * 3 % people.length],
        i % 2 === 0 ? dealIds[i % dealSeeds.length] : null,
        t - i * DAY
      )
    );
  });
  statements.push(db.prepare(`UPDATE workspaces SET seeded_at = ? WHERE owner_sub = ?`).bind(t, owner));
  for (let i = 0; i < statements.length; i += 40) await db.batch(statements.slice(i, i + 40));
}
async function clearWorkspace(db, owner) {
  await db.batch(
    ["activities", "tasks", "files", "deals", "contacts", "companies"].map(
      (table) => db.prepare(`DELETE FROM ${table} WHERE owner_sub = ?`).bind(owner)
    )
  );
  await db.prepare(`UPDATE workspaces SET seeded_at = NULL WHERE owner_sub = ?`).bind(owner).run();
}

// src/worker/routes/workspace.ts
var workspace = new Hono3();
async function ensureWorkspace(db, owner, name) {
  const row = await db.prepare(`SELECT name, seeded_at FROM workspaces WHERE owner_sub = ?`).bind(owner).first();
  if (row) return row;
  await db.prepare(`INSERT INTO workspaces (owner_sub, name, created_at) VALUES (?, ?, ?)`).bind(owner, name, now()).run();
  await seedWorkspace(db, owner);
  return { name, seeded_at: now() };
}
workspace.get("/me", async (c) => {
  const user = c.get("user");
  const db = c.get("db");
  const ws = await ensureWorkspace(db, user.sub, `${user.name?.split(" ")[0] ?? "Your"}'s workspace`);
  const body = {
    user: { sub: user.sub, name: user.name, email: user.email, picture: user.picture },
    workspace: { name: ws.name, seededAt: ws.seeded_at },
    capabilities: {
      database: true,
      files: Boolean(c.env.FILES),
      auth: c.env.APP_PASSWORD ? "password" : authMode(c.env, c.req.raw) === "freebuff" ? "freebuff" : "development"
    }
  };
  return privateJson(c, body);
});
workspace.patch("/workspace", async (c) => {
  const { name } = await c.req.json();
  const clean2 = name?.trim().slice(0, 60);
  if (!clean2) return c.json({ error: "Name is required." }, 400);
  await c.get("db").prepare(`UPDATE workspaces SET name = ? WHERE owner_sub = ?`).bind(clean2, c.get("user").sub).run();
  return privateJson(c, { ok: true });
});
workspace.post("/workspace/reset", async (c) => {
  const db = c.get("db");
  const owner = c.get("user").sub;
  await clearWorkspace(db, owner);
  await seedWorkspace(db, owner);
  return privateJson(c, { ok: true });
});
workspace.delete("/workspace/data", async (c) => {
  await clearWorkspace(c.get("db"), c.get("user").sub);
  return privateJson(c, { ok: true });
});
workspace.get("/overview", async (c) => {
  const db = c.get("db");
  const owner = c.get("user").sub;
  const t = now();
  const startOfMonth = new Date(t);
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);
  const startOfLast = new Date(startOfMonth);
  startOfLast.setMonth(startOfLast.getMonth() - 1);
  const month = startOfMonth.toISOString().slice(0, 10);
  const lastMonth = startOfLast.toISOString().slice(0, 10);
  const sixMonths = new Date(startOfMonth);
  sixMonths.setMonth(sixMonths.getMonth() - 5);
  const [pipeline, wonThis, wonLast, openDeals, newContacts, tasksDue, stages, revenue, activity, tasks2] = await db.batch([
    db.prepare(`SELECT COALESCE(SUM(value),0) AS v FROM deals WHERE owner_sub = ? AND stage NOT IN ('won','lost')`).bind(owner),
    db.prepare(`SELECT COALESCE(SUM(value),0) AS v FROM deals WHERE owner_sub = ? AND stage = 'won' AND close_date >= ?`).bind(owner, month),
    db.prepare(`SELECT COALESCE(SUM(value),0) AS v FROM deals WHERE owner_sub = ? AND stage = 'won' AND close_date >= ? AND close_date < ?`).bind(owner, lastMonth, month),
    db.prepare(`SELECT COUNT(*) AS n FROM deals WHERE owner_sub = ? AND stage NOT IN ('won','lost')`).bind(owner),
    db.prepare(`SELECT COUNT(*) AS n FROM contacts WHERE owner_sub = ? AND created_at >= ?`).bind(owner, t - 30 * 864e5),
    db.prepare(`SELECT COUNT(*) AS n FROM tasks WHERE owner_sub = ? AND done_at IS NULL AND due_at IS NOT NULL AND due_at <= ?`).bind(owner, t + 864e5),
    db.prepare(`SELECT stage, COUNT(*) AS n, COALESCE(SUM(value),0) AS v FROM deals WHERE owner_sub = ? GROUP BY stage`).bind(owner),
    db.prepare(
      `SELECT substr(close_date, 1, 7) AS ym, COALESCE(SUM(value),0) AS v FROM deals
         WHERE owner_sub = ? AND stage = 'won' AND close_date >= ? GROUP BY ym ORDER BY ym`
    ).bind(owner, sixMonths.toISOString().slice(0, 10)),
    db.prepare(`${ACTIVITY_SELECT} WHERE a.owner_sub = ? ORDER BY a.created_at DESC LIMIT 8`).bind(owner),
    db.prepare(`${TASK_SELECT} WHERE t.owner_sub = ? AND t.done_at IS NULL ORDER BY t.due_at IS NULL, t.due_at ASC LIMIT 6`).bind(owner)
  ]);
  const months = [];
  const byMonth = new Map(revenue.results.map((r) => [r.ym, Number(r.v)]));
  for (let i = 0; i < 6; i++) {
    const d = new Date(sixMonths);
    d.setMonth(d.getMonth() + i);
    const key = d.toISOString().slice(0, 7);
    months.push({ label: d.toLocaleString("en", { month: "short" }), value: byMonth.get(key) ?? 0 });
  }
  const stageRows = stages.results;
  const body = {
    kpis: {
      pipelineValue: Number(pipeline.results[0].v),
      wonThisMonth: Number(wonThis.results[0].v),
      wonLastMonth: Number(wonLast.results[0].v),
      openDeals: Number(openDeals.results[0].n),
      newContacts: Number(newContacts.results[0].n),
      tasksDue: Number(tasksDue.results[0].n)
    },
    revenueSeries: months,
    stageTotals: ["lead", "qualified", "proposal", "negotiation", "won", "lost"].map((stage) => {
      const row = stageRows.find((r) => r.stage === stage);
      return { stage, count: Number(row?.n ?? 0), value: Number(row?.v ?? 0) };
    }),
    recentActivity: activity.results.map(mapActivity),
    upcomingTasks: tasks2.results.map(mapTask)
  };
  return privateJson(c, body);
});
workspace.get("/search", async (c) => {
  const q = (c.req.query("q") ?? "").trim();
  if (q.length < 1) return privateJson(c, { contacts: [], companies: [], deals: [] });
  const db = c.get("db");
  const owner = c.get("user").sub;
  const like = `%${q.replace(/[%_]/g, "")}%`;
  const [contacts2, companies3, deals2] = await db.batch([
    db.prepare(
      `SELECT id, first_name, last_name, email, hue FROM contacts WHERE owner_sub = ? AND (first_name || ' ' || last_name LIKE ? OR email LIKE ?) ORDER BY last_activity_at DESC LIMIT 5`
    ).bind(owner, like, like),
    db.prepare(`SELECT id, name, domain, hue FROM companies WHERE owner_sub = ? AND name LIKE ? ORDER BY name LIMIT 5`).bind(owner, like),
    db.prepare(`SELECT id, title, stage, value FROM deals WHERE owner_sub = ? AND title LIKE ? ORDER BY updated_at DESC LIMIT 5`).bind(owner, like)
  ]);
  return privateJson(c, {
    contacts: contacts2.results.map((r) => ({
      id: r.id,
      name: `${r.first_name} ${r.last_name}`.trim(),
      email: r.email,
      hue: r.hue
    })),
    companies: companies3.results,
    deals: deals2.results
  });
});

